ALTER TABLE resume_versions ADD COLUMN parent_resume_id INTEGER REFERENCES resume_versions(id);
ALTER TABLE document_versions ADD COLUMN ai_call_id INTEGER REFERENCES ai_calls(id);
CREATE INDEX resumes_parent ON resume_versions(parent_resume_id);
CREATE INDEX documents_call ON document_versions(ai_call_id);
CREATE TRIGGER ready_resume_immutable BEFORE UPDATE OF original_filename,file_path,file_type,sha256,extracted_text,reviewed_content_json,status,reviewed_at,parent_resume_id ON resume_versions WHEN OLD.status='ready' BEGIN SELECT RAISE(ABORT,'approved resume is immutable; create a version'); END;
CREATE TRIGGER resume_source_immutable BEFORE UPDATE OF original_filename,file_path,file_type,sha256,parent_resume_id ON resume_versions BEGIN SELECT RAISE(ABORT,'upload source is immutable'); END;
CREATE TRIGGER extracted_resume_immutable BEFORE UPDATE OF extracted_text ON resume_versions WHEN OLD.extracted_text IS NOT NULL BEGIN SELECT RAISE(ABORT,'raw extraction is immutable'); END;
CREATE TRIGGER document_call_immutable BEFORE UPDATE OF ai_call_id ON document_versions BEGIN SELECT RAISE(ABORT,'document provenance is immutable'); END;
CREATE TRIGGER document_parent_check BEFORE INSERT ON document_versions WHEN NEW.parent_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions p JOIN preparation_runs old ON old.id=p.run_id JOIN preparation_runs new ON new.id=NEW.run_id WHERE p.id=NEW.parent_document_id AND p.kind=NEW.kind AND old.job_id=new.job_id AND (p.run_id=NEW.run_id OR new.source_document_id=p.id)) BEGIN SELECT RAISE(ABORT,'invalid document parent'); END;
CREATE TRIGGER document_call_check BEFORE INSERT ON document_versions WHEN NEW.ai_call_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ai_calls WHERE id=NEW.ai_call_id AND run_id=NEW.run_id AND status='succeeded') BEGIN SELECT RAISE(ABORT,'invalid document AI provenance'); END;
CREATE TRIGGER run_sources_check BEFORE INSERT ON preparation_runs WHEN NOT EXISTS (SELECT 1 FROM jobs WHERE id=NEW.job_id AND status='ready') OR NOT EXISTS (SELECT 1 FROM resume_versions WHERE id=NEW.resume_version_id AND status='ready') OR (NEW.source_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions d JOIN preparation_runs r ON r.id=d.run_id WHERE d.id=NEW.source_document_id AND r.job_id=NEW.job_id)) BEGIN SELECT RAISE(ABORT,'run requires reviewed sources and matching revision job'); END;
CREATE TRIGGER capture_source_immutable BEFORE UPDATE OF resume_version_id,job_id,capture_type,supplied_url ON intake_captures BEGIN SELECT RAISE(ABORT,'capture source is immutable'); END;
CREATE TRIGGER capture_terminal_immutable BEFORE UPDATE ON intake_captures WHEN OLD.status IN ('succeeded','failed','interrupted') BEGIN SELECT RAISE(ABORT,'capture is complete; create another attempt'); END;
CREATE TRIGGER ai_source_immutable BEFORE UPDATE OF intake_capture_id,run_id,purpose,provider,model,request_json ON ai_calls BEGIN SELECT RAISE(ABORT,'AI request is immutable'); END;
CREATE TRIGGER ai_terminal_immutable BEFORE UPDATE ON ai_calls WHEN OLD.status IN ('succeeded','failed','interrupted') BEGIN SELECT RAISE(ABORT,'AI call is complete; create another attempt'); END;
CREATE TRIGGER validation_call_check BEFORE INSERT ON document_validations WHEN NEW.ai_call_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ai_calls a JOIN document_versions d ON d.run_id=a.run_id WHERE d.id=NEW.document_id AND a.id=NEW.ai_call_id AND a.status='succeeded') BEGIN SELECT RAISE(ABORT,'validation AI call must belong to document run'); END;
CREATE TRIGGER validation_ready_check BEFORE INSERT ON document_validations WHEN EXISTS (SELECT 1 FROM document_versions WHERE id=NEW.document_id AND render_status='ready') BEGIN SELECT RAISE(ABORT,'ready validation is frozen; create a revision'); END;
CREATE TRIGGER validation_no_update BEFORE UPDATE ON document_validations BEGIN SELECT RAISE(ABORT,'validations are append-only'); END;
CREATE TRIGGER validation_no_delete BEFORE DELETE ON document_validations BEGIN SELECT RAISE(ABORT,'validations are append-only'); END;
CREATE TRIGGER document_ready_checks BEFORE UPDATE OF render_status ON document_versions WHEN NEW.render_status='ready' AND ((SELECT count(DISTINCT check_type) FROM document_validations WHERE document_id=NEW.id AND check_type IN ('structure','facts','pdf'))!=3 OR EXISTS (SELECT 1 FROM document_validations v WHERE v.document_id=NEW.id AND v.id=(SELECT max(v2.id) FROM document_validations v2 WHERE v2.document_id=NEW.id AND v2.check_type=v.check_type) AND v.result='failed')) BEGIN SELECT RAISE(ABORT,'document has missing or failed validation'); END;
CREATE TRIGGER document_insert_pending BEFORE INSERT ON document_versions WHEN NEW.render_status!='pending' BEGIN SELECT RAISE(ABORT,'new documents must await validation'); END;
CREATE TRIGGER application_documents_insert BEFORE INSERT ON applications WHEN (NEW.resume_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions d JOIN preparation_runs r ON r.id=d.run_id WHERE d.id=NEW.resume_document_id AND d.kind='resume' AND d.render_status='ready' AND r.job_id=NEW.job_id)) OR (NEW.cover_letter_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions d JOIN preparation_runs r ON r.id=d.run_id WHERE d.id=NEW.cover_letter_document_id AND d.kind='cover_letter' AND d.render_status='ready' AND r.job_id=NEW.job_id)) BEGIN SELECT RAISE(ABORT,'submission documents must be ready and match job and kind'); END;
CREATE TRIGGER application_documents_update BEFORE UPDATE OF job_id,resume_document_id,cover_letter_document_id ON applications WHEN (NEW.resume_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions d JOIN preparation_runs r ON r.id=d.run_id WHERE d.id=NEW.resume_document_id AND d.kind='resume' AND d.render_status='ready' AND r.job_id=NEW.job_id)) OR (NEW.cover_letter_document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions d JOIN preparation_runs r ON r.id=d.run_id WHERE d.id=NEW.cover_letter_document_id AND d.kind='cover_letter' AND d.render_status='ready' AND r.job_id=NEW.job_id)) BEGIN SELECT RAISE(ABORT,'submission documents must be ready and match job and kind'); END;
CREATE TRIGGER no_resume_delete BEFORE DELETE ON resume_versions BEGIN SELECT RAISE(ABORT,'resume history is retained'); END;
CREATE TRIGGER no_run_delete BEFORE DELETE ON preparation_runs BEGIN SELECT RAISE(ABORT,'run history is retained'); END;
CREATE TRIGGER no_document_delete BEFORE DELETE ON document_versions BEGIN SELECT RAISE(ABORT,'document history is retained'); END;
CREATE TRIGGER no_capture_delete BEFORE DELETE ON intake_captures BEGIN SELECT RAISE(ABORT,'capture history is retained'); END;
CREATE TRIGGER no_call_delete BEFORE DELETE ON ai_calls BEGIN SELECT RAISE(ABORT,'AI history is retained'); END;
